        major, minor, patch, prerelease = parsed
        # Return a key that can be compared
        # We need to handle pre-release comparison specially
        return (major, minor, patch, prerelease is None, prerelease or [])

    # Use stable sort with custom comparison
    from functools import cmp_to_key

    def compare_versions(v1, v2):
        p1 = parse_version(v1)
        p2 = parse_version(v2)

        major1, minor1, patch1, pre1 = p1
        major2, minor2, patch2, pre2 = p2

